mapper.select:
SELECT id, tenant_id, task_id, project_id, plan_revision_id, plan_revision_no, assessment_id, assessment_version, checklist_id, checklist_version, grade_code, initiator_user_id, initiator_project_scope_version, source_snapshot_version, status_code, hold_reason_code, current_node_no, previous_approval_instance_id, replacement_approval_instance_id, decide_time, rejection_reason, withdraw_user_id, withdraw_time, withdraw_reason, version, creator, create_time, updater, update_time, deleted, lead_time_enabled_flag, source_task_version, source_plan_version, source_cutover_type_code, source_network_mode_code, source_schedule_time, lead_rule_version, lead_timezone_id, lead_plan_submit_time, lead_required_days, lead_actual_natural_days, lead_late_submission_flag, project_version, project_code, project_name, customer_id, customer_code, customer_name, department_id, department_code, department_name, project_scope_version FROM cut_approval_instance
WHERE tenant_id = #{query.tenantId}
  AND task_id = #{query.taskId}
  AND plan_revision_id = #{query.planRevisionId}
  AND deleted = b'0'
FOR UPDATE

SELECT id, tenant_id, task_id, project_id, plan_revision_id, plan_revision_no, assessment_id, assessment_version, checklist_id, checklist_version, grade_code, initiator_user_id, initiator_project_scope_version, source_snapshot_version, status_code, hold_reason_code, current_node_no, previous_approval_instance_id, replacement_approval_instance_id, decide_time, rejection_reason, withdraw_user_id, withdraw_time, withdraw_reason, version, creator, create_time, updater, update_time, deleted, lead_time_enabled_flag, source_task_version, source_plan_version, source_cutover_type_code, source_network_mode_code, source_schedule_time, lead_rule_version, lead_timezone_id, lead_plan_submit_time, lead_required_days, lead_actual_natural_days, lead_late_submission_flag, project_version, project_code, project_name, customer_id, customer_code, customer_name, department_id, department_code, department_name, project_scope_version FROM cut_approval_instance
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.approvalInstanceId}
  AND deleted = b'0'
FOR UPDATE

mapper.update:
UPDATE cut_approval_instance
SET hold_reason_code = #{query.holdReasonCode},
    version = #{query.expectedVersion} + 1,
    updater = #{query.updater},
    update_time = #{query.updateTime}
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.approvalInstanceId}
  AND status_code = 'PENDING'
  AND version = #{query.expectedVersion}
  AND deleted = b'0'

UPDATE cut_approval_instance
SET status_code = 'WITHDRAWN', hold_reason_code = NULL,
    withdraw_user_id = #{query.withdrawUserId}, withdraw_time = #{query.withdrawTime}, withdraw_reason = #{query.withdrawReason},
    version = version + 1, updater = #{query.updater}, update_time = #{query.updateTime}
WHERE tenant_id = #{query.tenantId} AND id = #{query.id} AND task_id = #{query.taskId}
  AND plan_revision_id = #{query.planRevisionId} AND version = #{query.version}
  AND status_code = 'PENDING' AND deleted = b'0'
